export type ParsedCreateAssetInstruction<
  TProgram extends string = typeof FOUNDER_VILLAGE_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    creator: TAccountMetas[0];
    asset: TAccountMetas[1];
    contributionMint: TAccountMetas[2];
    speTreasury: TAccountMetas[3];
    capitalVault: TAccountMetas[4];
    incomeVault: TAccountMetas[5];
    contributionTokenProgram: TAccountMetas[6];
    systemProgram: TAccountMetas[7];
    eventAuthority: TAccountMetas[8];
    program: TAccountMetas[9];
  };
  data: CreateAssetInstructionData;
};

export function parseCreateAssetInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedCreateAssetInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 10) {
    throw new SolanaError(SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS, {
      actualAccountMetas: instruction.accounts.length,
      expectedAccountMetas: 10,
    });
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      creator: getNextAccount(),
      asset: getNextAccount(),
      contributionMint: getNextAccount(),
      speTreasury: getNextAccount(),
      capitalVault: getNextAccount(),
      incomeVault: getNextAccount(),
      contributionTokenProgram: getNextAccount(),
      systemProgram: getNextAccount(),
      eventAuthority: getNextAccount(),
      program: getNextAccount(),
    },
    data: getCreateAssetInstructionDataDecoder().decode(instruction.data),
  };
}
